/// Pure invite-link parsing and building. No plugin imports — everything in
/// this file is unit-testable without platform channels.
///
/// Invite codes are 6 characters drawn from [InviteLinks.codeAlphabet]
/// (no I/L/O/0/1 to avoid transcription mistakes) and are generated by the
/// game data sources; this file only validates/normalizes them.
///
/// It also owns the app's deep-link ROUTE TABLE ([InviteLinks.parse] ->
/// [DeepLink]). Every path the native apps claim as a Universal Link / App
/// Link (web/.well-known/apple-app-site-association and the autoVerify
/// intent-filter in AndroidManifest.xml) must have a case here; keep the three
/// in sync via [InviteLinks.claimedPathPrefixes].
library;

import 'package:equatable/equatable.dart';

/// A parsed, validated deep link. Sealed so consumers `switch` exhaustively
/// and a new route type is a compile error everywhere it must be handled.
///
/// Route table (https://taskmaster-app-3d480.web.app/... or taskcaster://...):
///   /join/?code=ABC234[&ref=uid]   -> [JoinGameLink]  (also /join/ABC234)
///   /?join=ABC234[&ref=uid]        -> [JoinGameLink]  (web "Play in browser";
///                                     NOT claimed by the native apps)
///   /p/<postId>                    -> [FeedPostLink]  (reserved for WP-09)
///   /t/<taskId>                    -> [TaskLink]      (reserved)
///   /c/<challengeId>               -> [ChallengeLink] (reserved for WP-09)
sealed class DeepLink extends Equatable {
  const DeepLink();
}

/// Join the game with invite [code]; [ref] is the inviter's uid, if carried.
final class JoinGameLink extends DeepLink {
  final String code;
  final String? ref;

  const JoinGameLink(this.code, {this.ref});

  @override
  List<Object?> get props => [code, ref];
}

/// A shared Arena feed post (`/p/<postId>`). Reserved: nothing consumes it yet.
final class FeedPostLink extends DeepLink {
  final String postId;

  const FeedPostLink(this.postId);

  @override
  List<Object?> get props => [postId];
}

/// A shared task (`/t/<taskId>`). Reserved: nothing consumes it yet.
final class TaskLink extends DeepLink {
  final String taskId;

  const TaskLink(this.taskId);

  @override
  List<Object?> get props => [taskId];
}

/// A shared challenge (`/c/<challengeId>`). Reserved: nothing consumes it yet.
final class ChallengeLink extends DeepLink {
  final String challengeId;

  const ChallengeLink(this.challengeId);

  @override
  List<Object?> get props => [challengeId];
}

/// Builds and parses the shareable invite links.
class InviteLinks {
  InviteLinks._();

  /// Characters a valid invite code may contain (matches the generator in the
  /// game data sources).
  static const String codeAlphabet = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';

  static const int codeLength = 6;

  /// Custom scheme handled by the Android intent-filter and the iOS
  /// CFBundleURLTypes entry: taskcaster://join?code=X
  static const String appScheme = 'taskcaster';
  static const String appHost = joinSegment;

  /// Firebase Hosting domain that serves web/join/index.html and the
  /// .well-known association files.
  static const String webHost = 'taskmaster-app-3d480.web.app';

  /// First path segment of each route (see [DeepLink]).
  static const String joinSegment = 'join';
  static const String postSegment = 'p';
  static const String taskSegment = 't';
  static const String challengeSegment = 'c';

  /// Query parameter the Flutter web app reads at `/` ("Play in browser").
  static const String webJoinParam = 'join';

  /// Path prefixes the native apps claim on [webHost]. Must match the
  /// apple-app-site-association `components` and the Android autoVerify
  /// intent-filter `pathPrefix`es (a unit test pins both files to this list).
  static const List<String> claimedPathPrefixes = [
    '/$joinSegment',
    '/$postSegment/',
    '/$taskSegment/',
    '/$challengeSegment/',
  ];

  static final RegExp _codePattern =
      RegExp('^[$codeAlphabet]{$codeLength}\$');

  /// Firestore-style document ids (auto ids are 20 chars of [A-Za-z0-9]).
  static final RegExp _idPattern = RegExp(r'^[A-Za-z0-9_-]{1,128}$');

  /// The canonical shareable join URL for [code]. On a phone with the app
  /// installed it opens the app directly (Universal Link / verified App
  /// Link); otherwise it lands on the static web/join/index.html page, which
  /// offers "Play in browser" plus the store buttons.
  ///
  /// When [ref] (the inviter's uid) is supplied it is carried through as a
  /// `ref=` query param, so the joiner can auto-friend the person who invited
  /// them once the join succeeds.
  static String joinUrl(String code, {String? ref}) {
    final base = 'https://$webHost/join/?code=${Uri.encodeQueryComponent(code)}';
    if (ref == null || ref.trim().isEmpty) return base;
    return '$base&ref=${Uri.encodeQueryComponent(ref.trim())}';
  }

  /// Where the join page's "Play in browser" button sends the user: the
  /// Flutter web app root with `?join=CODE`, read via `Uri.base` at startup.
  static String playInBrowserUrl(String code, {String? ref}) {
    final base =
        'https://$webHost/?$webJoinParam=${Uri.encodeQueryComponent(code)}';
    if (ref == null || ref.trim().isEmpty) return base;
    return '$base&ref=${Uri.encodeQueryComponent(ref.trim())}';
  }

  /// Parses [uri] against the route table (see [DeepLink]). Returns null for
  /// links this app does not own or whose parameters are missing/invalid.
  ///
  /// [anyHost] skips the host check for http(s) links. Use it ONLY for the
  /// web app's own launch URL (`Uri.base`), which may be served from the
  /// firebaseapp.com alias, a preview channel or localhost.
  static DeepLink? parse(Uri uri, {bool anyHost = false}) {
    final String route;
    final List<String> rest;
    if (uri.scheme == appScheme) {
      // taskcaster://join?code=X  /  taskcaster://p/<id>
      route = uri.host;
      rest = uri.pathSegments.where((s) => s.isNotEmpty).toList();
    } else if (uri.scheme == 'https' || uri.scheme == 'http') {
      if (!anyHost && uri.host != webHost) return null;
      final segments = uri.pathSegments.where((s) => s.isNotEmpty).toList();
      if (segments.isEmpty) {
        // Web root: /?join=CODE ("Play in browser").
        final code = normalizeCode(uri.queryParameters[webJoinParam]);
        if (code == null) return null;
        return JoinGameLink(code, ref: _cleanRef(uri.queryParameters['ref']));
      }
      route = segments.first;
      rest = segments.sublist(1);
    } else {
      return null;
    }

    switch (route) {
      case joinSegment:
        final code = normalizeCode(uri.queryParameters['code'] ??
            (rest.isNotEmpty ? rest.first : null));
        if (code == null) return null;
        return JoinGameLink(code, ref: _cleanRef(uri.queryParameters['ref']));
      case postSegment:
        final id = _idFrom(rest);
        return id == null ? null : FeedPostLink(id);
      case taskSegment:
        final id = _idFrom(rest);
        return id == null ? null : TaskLink(id);
      case challengeSegment:
        final id = _idFrom(rest);
        return id == null ? null : ChallengeLink(id);
      default:
        return null;
    }
  }

  static String? _idFrom(List<String> rest) {
    if (rest.length != 1) return null;
    return _idPattern.hasMatch(rest.first) ? rest.first : null;
  }

  /// True when [code] is exactly [codeLength] characters from [codeAlphabet].
  static bool isValidCode(String code) => _codePattern.hasMatch(code);

  /// Trims/uppercases [raw] and returns it when it is a valid invite code,
  /// otherwise null. Lowercase input is accepted (users retype codes).
  static String? normalizeCode(String? raw) {
    if (raw == null) return null;
    final code = raw.trim().toUpperCase();
    return isValidCode(code) ? code : null;
  }

  /// Extracts an invite code from a deep link: [parse] restricted to
  /// [JoinGameLink]. Accepts taskcaster://join?code=X, the https
  /// /join/?code=X landing link (http tolerated), /join/X and /?join=X.
  ///
  /// Returns null for any other URI or when the code is missing/invalid.
  static String? codeFromUri(Uri uri) {
    final link = parse(uri);
    return link is JoinGameLink ? link.code : null;
  }

  /// Extracts the inviter reference (`ref=`) from a deep link, when present.
  ///
  /// Only returns a value for join links this app recognises and only when a
  /// valid invite code is ALSO present (a bare `ref` with no code is
  /// meaningless). The ref is an opaque uid, so it is only trimmed. Returns
  /// null when absent/blank.
  static String? refFromUri(Uri uri) {
    final link = parse(uri);
    return link is JoinGameLink ? link.ref : null;
  }

  /// Extracts the inviter reference (`ref=`) from a Play Install Referrer
  /// string of the form `invite_code=X&ref=Y` (URL-decoded or still-encoded).
  /// Only returns a value when a valid invite code is also present. Returns
  /// null when absent/blank/malformed.
  static String? refFromReferrer(String? referrer) {
    if (referrer == null || referrer.trim().isEmpty) return null;
    if (codeFromReferrer(referrer) == null) return null;

    final candidates = <String>{referrer};
    try {
      candidates.add(Uri.decodeComponent(referrer));
    } on ArgumentError {
      // Malformed percent-encoding — the raw pass still runs.
    }

    for (final candidate in candidates) {
      Map<String, String> params;
      try {
        params = Uri.splitQueryString(candidate);
      } on ArgumentError {
        continue;
      }
      final ref = _cleanRef(params['ref']);
      if (ref != null) return ref;
    }
    return null;
  }

  static String? _cleanRef(String? raw) {
    if (raw == null) return null;
    final ref = raw.trim();
    return ref.isEmpty ? null : ref;
  }

  /// Extracts an invite code from a Play Install Referrer string.
  ///
  /// Play delivers the `referrer=` query parameter of the store URL, usually
  /// already URL-decoded (`invite_code=ABC234`, possibly alongside utm_*
  /// params) but occasionally still encoded (`invite_code%3DABC234`) — both
  /// forms are handled. Returns null when absent or invalid.
  static String? codeFromReferrer(String? referrer) {
    if (referrer == null || referrer.trim().isEmpty) return null;

    // Try the raw string first, then a defensively-decoded copy.
    final candidates = <String>{referrer};
    try {
      candidates.add(Uri.decodeComponent(referrer));
    } on ArgumentError {
      // Malformed percent-encoding — the raw pass still runs.
    }

    for (final candidate in candidates) {
      Map<String, String> params;
      try {
        params = Uri.splitQueryString(candidate);
      } on ArgumentError {
        continue;
      }
      final code = normalizeCode(params['invite_code']);
      if (code != null) return code;
    }
    return null;
  }
}
